export interface ToolSeo {
  title: string;        // keyword-rich <title> (the site name is appended by the layout template)
  description: string;  // meta description, ~150 chars
  intro: string;        // visible paragraph that explains the tool to people and crawlers
  faqs: [string, string][];
  kind: "UtilityApplication" | "MultimediaApplication" | "BusinessApplication" | "DeveloperApplication";
}

const PRIVATE = ["Are my files uploaded anywhere?", "No. This tool runs in your browser, so your file stays on your device and is never sent to a server."];
const FREE = (what: string): [string, string] => [`Is ${what} really free?`, "Yes. It is free, needs no account, and adds no watermark."];

